function validate([startGene, endGene, bank]) {
  const gene = /^[ACGT]{8}$/;
  if (typeof startGene !== 'string' || !gene.test(startGene)) return 'startGene must be 8 letters from A, C, G, T.';
  if (typeof endGene !== 'string' || !gene.test(endGene)) return 'endGene must be 8 letters from A, C, G, T.';
  if (!Array.isArray(bank) || bank.length > 10) return 'bank holds at most 10 genes.';
  if (bank.some(g => typeof g !== 'string' || !gene.test(g))) return 'Every bank gene must be 8 letters from A, C, G, T.';
  return null;
}

