function minMutation(startGene, endGene, bank) {
  const valid = new Set(bank);
  const letters = ['A', 'C', 'G', 'T'];
  const seen = new Set([startGene]);
  let queue = [startGene];
  let steps = 0;

  while (queue.length > 0) {
    const next = [];
    for (const gene of queue) {
      if (gene === endGene) {
        return steps;
      }
      for (let i = 0; i < gene.length; i++) {
        for (const letter of letters) {
          const mutated = gene.slice(0, i) + letter + gene.slice(i + 1);
          if (valid.has(mutated) && !seen.has(mutated)) {
            seen.add(mutated);
            next.push(mutated);
          }
        }
      }
    }
    queue = next;
    steps++;
  }
  return -1;
}

