function minMutation(startGene, endGene, bank) {
  // Bellman-Ford style relaxation over the start gene and the bank genes.
  const nodes = [startGene, ...bank];
  const differ = (a, b) => { let d = 0; for (let k = 0; k < 8; k++) if (a[k] !== b[k]) d++; return d; };
  const dist = nodes.map((_, k) => (k === 0 ? 0 : Infinity));
  for (let round = 0; round < nodes.length; round++)
    for (let a = 0; a < nodes.length; a++)
      for (let b = 1; b < nodes.length; b++)
        if (dist[a] + 1 < dist[b] && differ(nodes[a], nodes[b]) === 1) dist[b] = dist[a] + 1;
  if (startGene === endGene) return 0;
  let best = Infinity;
  for (let k = 1; k < nodes.length; k++) if (nodes[k] === endGene) best = Math.min(best, dist[k]);
  return best === Infinity ? -1 : best;
}

