function generate(rand, size) {
  const letters = 'ACGT';
  const pick = () => letters[Math.floor(rand() * 4)];
  const randomGene = () => Array.from({ length: 8 }, pick).join('');
  const mutate = gene => { const i = Math.floor(rand() * 8); return gene.slice(0, i) + pick() + gene.slice(i + 1); };
  const startGene = randomGene();
  const count = size === 'large' ? 10 : Math.floor(rand() * 11);
  const bank = [];
  let current = startGene;
  while (bank.length < count) {
    const roll = rand();
    if (roll < 0.7) current = mutate(current);
    else if (roll < 0.93) current = mutate(bank.length ? bank[Math.floor(rand() * bank.length)] : startGene);
    else current = randomGene();
    bank.push(current);
  }
  const roll = rand();
  let endGene;
  if (roll < 0.55 && bank.length) endGene = bank[Math.floor(rand() * bank.length)];
  else if (roll < 0.8 && bank.length) endGene = bank[bank.length - 1];
  else if (roll < 0.88) endGene = mutate(current);
  else if (roll < 0.94) endGene = startGene;
  else endGene = randomGene();
  return [startGene, endGene, bank];
}
